model:
package examples.Shapes {

class Shape {
  sides:Int

  fun area : Real

}

class Angle {
  value:Int

  fun eq(other:Angle) : Bool
  {
    value = other.value
  }

  req value >= 0 && value <= 360
}

class TAngle extending Angle {

  req value < 180
}

class Triangle extending Shape {
  a:TAngle
  b:TAngle
  c:TAngle
  base:Int
  height:Int

  req sides = 3

  fun area : Real
  {
    base * height / 2
  }

  req Angles: a.value + b.value + c.value = 180
}

class Equilateral extending Triangle {

  req a.eq(b) && b.eq(c)
}

class Obtuse extending Triangle {

  req a.value > 90 || b.value > 90 || c.value > 90
}


}
